fun getNewsDetailsList(): List<NewsDetailsVO> { // 返回固定基线数据，保证首启可见内容稳定。 return baseNewsList }
fun hasMoreNews(page: Int): Boolean = page < TOTAL_NEWS_PAGES
fun getNewsPage(page: Int, pageSize: Int = 5): List<NewsDetailsVO> { // 通过复制基础数据构造分页效果，便于验证上拉加载流程。 if (!hasMoreNews(page) || pageSize <= 0) return emptyList() return List(pageSize) { index -> val seed = baseNewsList[(page * pageSize + index) % baseNewsList.size] seed.copy( id = "${seed.id}_p${page}_i${index}", title = if (page == 0) seed.title else "${seed.title} · 第${page + 1}页" ) } }
fun hasMoreComments(page: Int): Boolean = page < TOTAL_COMMENT_PAGES
fun getMoreComments(newsId: String, page: Int, pageSize: Int = 3): List<String> { // 生成可定位来源的评论文本，方便调试评论分页展示。 if (!hasMoreComments(page) || pageSize <= 0) return emptyList() return List(pageSize) { index -> val commentIndex = page * pageSize + index + 1 "[$newsId] 追加评论 $commentIndex：这是一条用于上拉加载的测试评论。" } } }

